#!/usr/bin/env node
// Local integration fixture: deterministic CLI protocol, never used in production.
import { createInterface } from "node:readline";
import { writeFile, readFile } from "node:fs/promises";
import { join } from "node:path";
const send = (value) => process.stdout.write(JSON.stringify(value) + "\n");
const threadId = "fixture-session",
  turnId = "fixture-turn";
if (process.env.MELANCHOLY_TOKEN)
  throw new Error("Connector credentials leaked to the child.");
createInterface({ input: process.stdin }).on("line", async (line) => {
  const message = JSON.parse(line);
  if (message.method === "initialize") send({ id: message.id, result: {} });
  if (message.method === "thread/start" || message.method === "thread/resume")
    send({ id: message.id, result: { thread: { id: threadId } } });
  if (message.method === "turn/start") {
    const prompt = message.params.input
      .map((part) => part.text || "")
      .join("\n");
    const attached = prompt.match(/Attached files \(local paths\):\n([^\n]+)/);
    if (attached) {
      const file = await readFile(attached[1]);
      await writeFile(
        join(process.cwd(), "attachment-read.txt"),
        String(file.length),
      );
    }
    send({ id: message.id, result: { turn: { id: turnId } } });
    send({
      method: "item/completed",
      params: {
        threadId,
        turnId,
        item: {
          type: "agentMessage",
          id: "intro",
          text: "Preparing two deliverables.",
        },
      },
    });
    send({
      id: 99,
      method: "item/commandExecution/requestApproval",
      params: {
        threadId,
        turnId,
        itemId: "operation",
        command: "fixture operation",
        cwd: process.cwd(),
      },
    });
  }
  if (message.id === 99 && message.result) {
    if (message.result.decision !== "decline")
      throw new Error("Fixture expected a refusal.");
    await writeFile(
      join(process.env.MELANCHOLY_OUTPUT_DIR, "generated.md"),
      "# Generated by the server\n\nDurable document output.",
    );
    await writeFile(
      join(process.env.MELANCHOLY_OUTPUT_DIR, "generated.csv"),
      "name,value\nfixture,42\n",
    );
    send({
      method: "item/completed",
      params: {
        threadId,
        turnId,
        item: {
          type: "agentMessage",
          id: "final",
          text: "The requested operation was declined. Two files are ready for delivery.",
        },
      },
    });
    send({
      method: "turn/completed",
      params: { threadId, turn: { id: turnId, status: "completed" } },
    });
  }
});
